ControlPropertyState.AutoRuleBindingString:
Set(
    varTotalAnswered,
    CountIf(
        colPQSGrade,
        IsCorrect = "Correct"
    ) + CountIf(
        colPQSGrade,
        IsCorrect = "Incorrect"
    ) + CountIf(
        colWIGrade,
        IsCorrect = "Correct"
    ) + CountIf(
        colWIGrade,
        IsCorrect = "Incorrect"
    )
);
//This is the message of the board being completed, the PDF will send no mather what
If(
    Confirm(
        If(
            varTotalAnswered < 20,
            User().FullName & " Board is not complete (less than 20 answered). Are you sure you want to finish?",
            varTotalAnswered >= 20,
            "Are you sure the Board is completed?"
        )
    ),
    Navigate(scrPlacement)
);
Set(
    varCorrect,
    If(
        CountRows(colPQSGrade) + CountRows(colWIGrade) = 0,
        0,
        RoundDown(
            (CountIf(
                colPQSGrade,
                IsCorrect = "Correct"
            ) + CountIf(
                colWIGrade,
                IsCorrect = "Correct"
            )) / (CountIf(
                colPQSGrade,
                IsCorrect = "Correct"
            ) + CountIf(
                colPQSGrade,
                IsCorrect = "Incorrect"
            ) + CountIf(
                colWIGrade,
                IsCorrect = "Correct"
            ) + CountIf(
                colWIGrade,
                IsCorrect = "Incorrect"
            )) * 100,
            0
        )
    )
);
Set(
    varBoardStatus,
    If(
        varCorrect >= 80,
        "Passed",
        "Failed"
    )
);
//Information for Report, this will update the List
Patch(
    EPIC_PQSBoardResults,
    LookUp(
        EPIC_PQSBoardResults,
        ID = VarSessionID
    ),
    {
        BoardStatus: varBoardStatus,
        TimesRefreshed: varRefreshCount,
        BoardType: "Board",
        Correct: CountIf(
            colPQSGrade,
            IsCorrect = "Correct"
        ) + CountIf(
            colWIGrade,
            IsCorrect = "Correct"
        ),
        Incorrect: CountIf(
            colPQSGrade,
            IsCorrect = "Incorrect"
        ) + CountIf(
            colWIGrade,
            IsCorrect = "Incorrect"
        )
    }
);
