// Send email
PQS_Email_PDF.Run(
    varHTML,
    "PQS_Board_" & ddVenue.SelectedText.Value & "_" & txtTech.Text & "_" & Text(
        Today(),
        "yyyymmdd"
    ) & ".pdf"
