    "Board summary email sent. :)",
    NotificationType.Success
);

//===== REFRESH COUNT ========

Set(varRefreshCount, Coalesce(varRefreshCount, 0) + 1);

// ===== MOD COUNT + TOTAL QUESTIONS =====
Set(varModCount, CountRows(colActiveMods));

Set(
    varTotalQuestions,
    Switch(
        varModCount,
        1, 30,
        2, 30,
        3, 32,
        4, 36,
        5, 41,
        41
    )
);

// ===== IDENTIFY SINGLE MOD =====
Set(
    varSingleModValue,
    If(varModCount = 1, First(colActiveMods).Value, Blank())
);

// ===== MOD 0 COUNT =====
Set(
    varMod0Count,
    If(
        varModCount = 1 && varSingleModValue = "0",
        varTotalQuestions,
        5
    )
);

// ===== REMAINING =====
Set(varRemainingQuestions, varTotalQuestions - varMod0Count);

// ===== NON-ZERO MOD COUNT =====
Set(
    varNonZeroModCount,
    CountRows(Filter(colActiveMods, Value <> "0"))
);

// ===== QUESTIONS PER MOD =====
Set(
    varQuestionsPerMod,
    If(
        varNonZeroModCount = 0,
        0,
        RoundDown(varRemainingQuestions / varNonZeroModCount, 0)
    )
);

// ===== CATEGORY SPLIT =====

// Here to set the number of A Questions

Set(
    varCatACount,
    If(
        varNonZeroModCount = 1,
        RoundDown(varQuestionsPerMod / 2, 0),
        3

    )
);

Set(varCatBCount, varQuestionsPerMod - varCatACount);

// ===== CLEANUP EXISTING QUESTIONS =====
RemoveIf(
    colPQSQ,
    IsBlank(
        LookUp(
            colPQSGrade,
            QuestionID = ID
        )
    )
);

// ===== MOD 0 PULL =====
Collect(
    colPQSQ,
    FirstN(
        Shuffle(
            Filter(
                varQuestionSource,
                Mod.Value = "0" &&
                !(ID in colPQSGrade.QuestionID) &&
                !(ID in colPQSQ.ID)
            )
        ),
        Max(
            0,
            varMod0Count - CountIf(colPQSQ, Mod.Value = "0")
        )
    )
);

// ===== A/B LOGIC (ALL NON-ZERO MODS, INCLUDING SINGLE MOD CASE) =====
If(
    varNonZeroModCount > 0,
    ForAll(
        Filter(colActiveMods, Value <> "0") As m,

        // --- CATEGORY A ---
        Collect(
            colPQSQ,
            FirstN(
                Shuffle(
                    Filter(
                        varQuestionSource,
                        Mod.Value = m.Value &&
                        Cat.Value = "A" &&
                        !(ID in colPQSGrade.QuestionID) &&
                        !(ID in colPQSQ.ID)
                    )
                ),
                Max(
                    0,
                    varCatACount -
                    CountIf(
                        colPQSQ,
                        Mod.Value = m.Value && Cat.Value = "A"
                    )
                )
            )
        );

        // --- CATEGORY B ---
        Collect(
            colPQSQ,
            FirstN(
                Shuffle(
                    Filter(
                        varQuestionSource,
                        Mod.Value = m.Value &&
                        Cat.Value = "B" &&
                        !(ID in colPQSGrade.QuestionID) &&
                        !(ID in colPQSQ.ID)
                    )
                ),
                Max(
                    0,
                    varCatBCount -
                    CountIf(
                        colPQSQ,
                        Mod.Value = m.Value && Cat.Value = "B"
                    )
                )
            )
        )
    )
);

With(
    {
        q: Lower(Trim(txtWIQuestion.Text)),
        a: Lower(Trim(txtWIAnswer.Text))
    },
    If(
        IsBlank(q) ||
        IsBlank(a) ||
        drWIMod.Selected.Value = "-" ||
        q in ["wi", "write-in", "write in","write in question","write-in question","wi question","w-i question"] ||
        a in ["wi", "correct", "incorrect","write in answer","write-in answer", "wi answer", "w-i answer"],

        Notify("Question, Answer and Mod required.", NotificationType.Error),

        Collect(
            colWIGrade,
            {
                QuestionID: GUID(),
                QNumber: "WI",
                Question: txtWIQuestion.Text,
                IsCorrect: "Correct",
                Mod: drWIMod.Selected.Value
            }
        );

        Patch(
            EPICWIQuestion,
            Defaults(EPICWIQuestion),
            {
                SessionID: varBoardSessionID,
                Question: txtWIQuestion.Text,
                Answer: txtWIAnswer.Text,
                Result: {Value: "Correct"},
                Manager: txtManager.Text,
                Date: Today(),
                Venue: ddVenue.SelectedText.Value,
                Mod: drWIMod.SelectedText
            }
        );

        Reset(txtWIAnswer);
        Reset(txtWIQuestion);
        Reset(drWIMod);
        Set(varShowWIPopup, false)
    )
)

